// ── CASE-BASED QUESTIONS (4 marks each: 4 sub-questions of 1 mark) ──
type Sub = CompetencyQuestion["subQuestions"][number];
const mc = (question: string, options: string[], correctIndex: number, answer: string, explanation: string): Sub => ({ question, options, correctIndex, answer, explanation });
const sa = (question: string, answer: string, explanation: string): Sub => ({ question, answer, explanation });
// Rotate the options of each multiple-choice part so the correct answer is not always in the same place.
const spread = (id: number, subs: Sub[]): Sub[] => subs.map((sq, j) => {
  if (!sq.options || sq.correctIndex === undefined) return sq;
  const n = sq.options.length;
  const target = (id + j) % n;
  const opts = sq.options.slice();
  [opts[sq.correctIndex], opts[target]] = [opts[target], opts[sq.correctIndex]];
  return { ...sq, options: opts, correctIndex: target };
});
const C = (id: number, caseTitle: string, caseDescription: string, subQuestions: Sub[]): CompetencyQuestion => ({ id, caseTitle, caseDescription, subQuestions: spread(id, subQuestions) });

